@layer components {
  /* Copy button: the look of a neutral button of the ViteHub theme, so it matches the buttons around it. */
  [data-slot="copy-button"] {
    align-items: center;
    background: transparent;
    border: 0;
    border-radius: calc(var(--vh-radius) * 0.75);
    color: var(--vh-text);
    cursor: pointer;
    display: inline-flex;
    flex-shrink: 0;
    font: inherit;
    font-size: 0.75rem;
    font-weight: 500;
    gap: 0.375rem;
    line-height: 1rem;
    padding: 0.375rem 0.625rem;
    transition: color 150ms ease-out, background-color 150ms ease-out, box-shadow 150ms ease-out;
  }

  [data-slot="copy-button"][data-size="xs"] {
    gap: 0.25rem;
    padding: 0.25rem 0.5rem;
  }

  [data-slot="copy-button"][data-size="md"] {
    font-size: 0.875rem;
    line-height: 1.25rem;
  }

  /* Without a label the button is a square around its icon. */
  [data-slot="copy-button"]:not(:has([data-slot="copy-button-label"])) {
    padding: 0.375rem;
  }

  [data-slot="copy-button"][data-size="xs"]:not(:has([data-slot="copy-button-label"])) {
    padding: 0.25rem;
  }

  [data-slot="copy-button"][data-variant="outline"] {
    background: var(--vh-bg);
    box-shadow: inset 0 0 0 1px var(--vh-border-accented);
  }

  [data-slot="copy-button"][data-variant="solid"] {
    background: var(--vh-highlighted);
    color: var(--vh-inverted);
  }

  @media (hover: hover) {
    [data-slot="copy-button"]:not([data-variant="solid"]):hover:not(:disabled) {
      background: var(--vh-bg-elevated);
    }

    [data-slot="copy-button"][data-variant="solid"]:hover:not(:disabled) {
      background: color-mix(in oklab, var(--vh-highlighted) 90%, transparent);
    }
  }

  [data-slot="copy-button"]:focus-visible {
    outline: 2px solid var(--vh-ring);
    outline-offset: 2px;
  }

  [data-slot="copy-button"]:disabled {
    cursor: not-allowed;
    opacity: 0.5;
  }

  [data-slot="copy-button"][data-loading] {
    cursor: progress;
  }

  [data-slot="copy-button-icon"] {
    flex: none;
    height: 1rem;
    opacity: 0.8;
    width: 1rem;
  }

  [data-slot="copy-button"][data-size="md"] [data-slot="copy-button-icon"] {
    height: 1.25rem;
    width: 1.25rem;
  }

  [data-slot="copy-button"][data-loading] [data-slot="copy-button-icon"] {
    animation: copy-button-spin 1s linear infinite;
  }

  @keyframes copy-button-spin {
    to {
      transform: rotate(360deg);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="copy-button"] {
      transition: none;
    }

    [data-slot="copy-button"][data-loading] [data-slot="copy-button-icon"] {
      animation: none;
    }
  }
}

export { default as CopyButton } from "./CopyButton.vue";
export type * from "./types.ts";
export { useCopy } from "./use-copy.ts";
export type { CopyValue, UseCopyOptions, UseCopyReturn } from "./use-copy.ts";

import type { CopyValue } from "./use-copy.ts";

export type CopyButtonVariant = "ghost" | "outline" | "solid";
export type CopyButtonSize = "xs" | "sm" | "md";

export interface CopyButtonProps {
  /** The text to copy, or a function that returns it. */
  value: CopyValue;
  /** The text in the button. Without it, the button shows only its icon and `copyLabel` names it. */
  label?: string;
  /** The name of an icon-only button. */
  copyLabel?: string;
  /** The text in place of `label` for `duration` ms after a copy, and the announcement. */
  copiedLabel?: string;
  /** The announcement when the browser refuses the copy. */
  failedLabel?: string;
  variant?: CopyButtonVariant;
  size?: CopyButtonSize;
  /** How long, in ms, the check shows after a copy. */
  duration?: number;
  /** Call a function `value` when the pointer enters the button or it gets focus, so the click copies text that is already loaded. */
  preload?: boolean;
  disabled?: boolean;
}

export interface CopyButtonEmits {
  copy: [];
  error: [];
}

export interface CopyButtonSlots {
  /** The text in the button, in place of `label`. */
  default?: () => unknown;
  /** The icon before a copy. Defaults to Lucide's `Copy`. */
  icon?: () => unknown;
  /** The icon for `duration` ms after a copy. Defaults to Lucide's `Check`. */
  "copied-icon"?: () => unknown;
}

import { getCurrentScope, type MaybeRefOrGetter, onScopeDispose, readonly, ref, type Ref, toValue } from "vue";

/** The text to copy, or a function that returns it, such as one that fetches the Markdown of a page. */
export type CopyValue = string | (() => string | Promise<string>);

export interface UseCopyOptions {
  /** How long, in ms, `copied` and `failed` stay `true`. A ref or a getter is read at each copy. */
  duration?: MaybeRefOrGetter<number | undefined>;
}

export interface UseCopyReturn {
  /** Writes the text to the clipboard. Resolves to `true` when it was copied. It never rejects. */
  copy: (value: CopyValue) => Promise<boolean>;
  /** `true` for `duration` ms after a copy. */
  copied: Readonly<Ref<boolean>>;
  /** `true` for `duration` ms after a copy that the browser refused. */
  failed: Readonly<Ref<boolean>>;
}

/** Writes the text. Resolves to `false` when the browser refuses, and rejects when the text failed to load. */
async function writeClipboard(value: CopyValue): Promise<boolean> {
  const text = typeof value === "function" ? value() : value;
  try {
    if (await writeClipboardApi(text)) return true;
  }
  catch {
    // Outside a secure context, such as a dev server on a LAN address, the clipboard API refuses.
  }
  // The older copy command still works there. When the text failed to load, this rethrows that failure.
  return copyWithCommand(await text);
}

/** Resolves to `false` when the browser has no clipboard API. */
async function writeClipboardApi(text: string | Promise<string>): Promise<boolean> {
  const clipboard = globalThis.navigator?.clipboard;
  if (typeof clipboard?.writeText !== "function") return false;
  if (typeof text === "string") await clipboard.writeText(text);
  // Safari allows a write only during the click. A ClipboardItem takes the pending text, so the write starts now.
  else if (typeof ClipboardItem === "function" && typeof clipboard.write === "function") {
    await clipboard.write([new ClipboardItem({ "text/plain": text.then((resolved) => new Blob([resolved], { type: "text/plain" })) })]);
  }
  else await clipboard.writeText(await text);
  return true;
}

/** Copies through a hidden text area and `document.execCommand("copy")`. Returns `false` when the browser refuses. */
function copyWithCommand(text: string): boolean {
  const doc = globalThis.document;
  if (typeof doc?.execCommand !== "function" || !doc.body) return false;
  const focused = doc.activeElement;
  const area = doc.createElement("textarea");
  area.value = text;
  area.readOnly = true;
  area.style.position = "fixed";
  area.style.opacity = "0";
  doc.body.append(area);
  area.focus({ preventScroll: true });
  area.select();
  try {
    return doc.execCommand("copy");
  }
  catch {
    return false;
  }
  finally {
    area.remove();
    if (focused instanceof HTMLElement) focused.focus({ preventScroll: true });
  }
}

/**
 * The clipboard logic of `CopyButton`, for a control that copies as one part of a larger action, such as the item
 * "Copy link" in a menu. The caller shows the result, for example with a toast.
 */
export function useCopy(options: UseCopyOptions = {}): UseCopyReturn {
  const copied = ref(false);
  const failed = ref(false);
  let timer: ReturnType<typeof setTimeout> | undefined;
  if (getCurrentScope()) onScopeDispose(() => clearTimeout(timer));

  async function copy(value: CopyValue): Promise<boolean> {
    clearTimeout(timer);
    copied.value = false;
    failed.value = false;
    try {
      copied.value = await writeClipboard(value);
    }
    catch {
      copied.value = false;
    }
    failed.value = !copied.value;
    timer = setTimeout(() => {
      copied.value = false;
      failed.value = false;
    }, toValue(options.duration) ?? 2_000);
    return copied.value;
  }

  return { copy, copied: readonly(copied), failed: readonly(failed) };
}
